function m2f_projectDdl(string $sql,array $columns,array $indexes,bool $counter):string {
 $lines=[];foreach(explode("\n",$sql) as $line){$remove=false;foreach($columns as $name)if(str_starts_with($line,'  '.m2f_quote($name).' '))$remove=true;foreach($indexes as $name)if(str_starts_with($line,'  KEY '.m2f_quote($name).' '))$remove=true;if(!$remove)$lines[]=$line;}$sql=preg_replace('/,\n\) ENGINE=/',"\n) ENGINE=",implode("\n",$lines));return $counter?preg_replace('/(\) ENGINE=InnoDB) AUTO_INCREMENT=[0-9]+ /','$1 ',$sql):$sql;
