function m2f_column(array $row,array $expected,?string $collation=null,bool $auto=false):void {
 $type=preg_replace('/\b(tinyint|smallint|mediumint|int|bigint)\([0-9]+\)/','$1',strtolower($row['COLUMN_TYPE']));$text=preg_match('/\A(?:char|varchar)\(/',$expected[0])===1;
