function m2f_claimReports(array $result,string $directory,array &$owned):void {
 foreach($result['quarantine']??[] as $report){m2f_assert(is_array($report)&&($report['private']??null)===true&&($report['report_written']??null)===true&&is_string($report['sha256']??null)&&preg_match('/\A[a-f0-9]{64}\z/D',$report['sha256'])===1&&is_int($report['bytes']??null),'PRIVATE_REPORT_RECEIPT');$path=$directory.'/marketplace_ownership_quarantine-'.$report['sha256'].'.json';$file=m2f_file($path);m2f_assert($file['sha256']===$report['sha256']&&$file['bytes']===$report['bytes'],'PRIVATE_REPORT_ACTUAL_BYTES');if(isset($owned[$path]))m2f_assert($owned[$path]===$file,'PRIVATE_REPORT_ALREADY_OWNED');$owned[$path]=$file;}
}
function m2f_cli(string $script,string $mode,string $configFile,?string $stateFile,array &$evidence,array &$owned,?string $mappingFile=null,?string $quarantineDir=null,bool $maintenance=false,string $role='command'):array {
 m2f_source();audit_guard_assert();$argv=[PHP_BINARY,$script,$mode,'--config-file='.$configFile];if($stateFile!==null){$argv[]='--repo-root='.audit_repo_dir();$argv[]='--state-file='.$stateFile;}if($mappingFile!==null)$argv[]='--mapping='.$mappingFile;if($quarantineDir!==null)$argv[]='--quarantine-dir='.$quarantineDir;if($maintenance)$argv[]='--maintenance-confirmed';$process=proc_open($argv,[['file','/dev/null','r'],['pipe','w'],['pipe','w']],$pipes,audit_repo_dir());m2f_assert(is_resource($process),'CHILD_START');$first=proc_get_status($process);$stdout='';$stderr='';
 try{m2f_assert(is_array($first)&&is_int($first['pid'])&&$first['pid']>0,'ACTUAL_CHILD_PID');$stdout=stream_get_contents($pipes[1]);$stderr=stream_get_contents($pipes[2]);}finally{foreach($pipes as $pipe)if(is_resource($pipe))fclose($pipe);$close=proc_close($process);}
 $native=$close;$origin='proc_close';if($close===-1&&$first['running']===false&&$first['signaled']===false&&is_int($first['exitcode'])&&$first['exitcode']>=0){$native=$first['exitcode'];$origin='actual_first_terminal_status';}$result=is_string($stdout)&&strlen($stdout)<=1048576?json_decode($stdout,true):null;$step=['script'=>basename($script),'script_sha256'=>hash_file('sha256',$script),'mode'=>$mode,'role'=>$role,'pid'=>$first['pid'],'first_running'=>$first['running'],'first_actual_exit'=>$first['exitcode'],'proc_close_exit'=>$close,'native_exit'=>$native,'native_exit_origin'=>$origin,'stdout_bytes'=>strlen((string)$stdout),'stdout_sha256'=>hash('sha256',(string)$stdout),'stderr_bytes'=>strlen((string)$stderr),'stderr_sha256'=>hash('sha256',(string)$stderr),'private_argv_values_omitted'=>true];
 if(is_array($result)&&!array_is_list($result)&&($result['mode']??null)===$mode&&in_array($result['state']??'', ['applicable','completed','incompatible','quarantined','blocked'],true)){$step['public_result']=$result;$step['actual_stdout_json']=$stdout;}$evidence['children'][]=$step;if($stateFile!==null&&file_exists($stateFile)){$actualState=m2f_file($stateFile);if(isset($owned[$stateFile]))m2f_assert($owned[$stateFile]===$actualState,'BOUND_STATE_BYTES_AND_IDENTITY_PRESERVED');$owned[$stateFile]=$actualState;}if(is_array($result)&&$quarantineDir!==null)m2f_claimReports($result,$quarantineDir,$owned);m2f_assert($native===0&&$step['stderr_bytes']===0&&isset($step['public_result'])&&($stateFile===null||($result['native_exit']??null)===0),'CHILD_NORMAL_NATIVE');return $result;
