/* Fixed, independent fatal metadata; never an error message, argument or trace. */
function m2m_shutdown(string $phase,?array $last,?array $primary,?array $cleanup):void {
 try {
  $type=$last['type']??null;
  $fatal=in_array($type,[E_ERROR,E_PARSE,E_CORE_ERROR,E_COMPILE_ERROR,E_USER_ERROR,E_RECOVERABLE_ERROR],true);
  if($last===null){$category='ORDERLY_SHUTDOWN';}
  elseif(!$fatal){$category='NONFATAL_SHUTDOWN';}
  else {
   $message=is_string($last['message']??null)?$last['message']:'';
   $category=(str_starts_with($message,'Allowed memory size of ')||str_starts_with($message,'Out of memory ('))?'MEMORY_EXHAUSTED':'FATAL_ERROR';
   unset($message);
  }
  $file=basename(is_string($last['file']??null)?$last['file']:'');
  $file=preg_match('/\A[A-Za-z0-9_.-]{1,128}\z/D',$file)===1?$file:'UNKNOWN_FILE';
  $record=['schema'=>1,'origin'=>'shutdown','phase'=>preg_match('/\A[a-z][a-z0-9_]{0,95}\z/D',$phase)===1?$phase:'unknown','type'=>is_int($type)?$type:0,'file'=>$file,'line'=>is_int($last['line']??null)?max(0,$last['line']):0,'memory_limit'=>ini_get('memory_limit'),'peak_bytes'=>memory_get_peak_usage(true),'category'=>$category,'primary_failure'=>$primary,'cleanup_failure'=>$cleanup];
  $bytes=m2f_json($record);if(strlen($bytes)>4096)return;
  $handle=@fopen('/run/audit/evidence/ms2-migration-shutdown.json','xb');
  if(is_resource($handle)){try{@fwrite($handle,$bytes);@fflush($handle);}finally{@fclose($handle);}}
 }catch(Throwable $ignored){}
}
